-- P5 科學科上學期整合題庫：5SC1–5SC7，共 560 題
-- 每個單元 80 題；可重複執行，不會重複新增。

begin;

do $$
begin
  if not exists (
    select 1 from public.curriculum_subjects
    where grade = 'P5' and code = 'science'
  ) then
    raise exception '找不到 P5 科學科（預期 subject code = science），請先建立科目。';
  end if;
end $$;

insert into public.curriculum_domains (subject_id, code, name_zh, name_en, sort_order)
select s.id, 'first_term', '科學科上學期', 'P5 Science First Term', 1
from public.curriculum_subjects s
where s.grade = 'P5' and s.code = 'science'
  and not exists (
    select 1 from public.curriculum_domains d
    where d.subject_id = s.id and d.code = 'first_term'
  );

with science_domain as (
  select d.id
  from public.curriculum_domains d
  join public.curriculum_subjects s on s.id = d.subject_id
  where s.grade = 'P5' and s.code = 'science' and d.code = 'first_term'
), units(code, title_zh, title_en, difficulty, sort_order, is_active) as (
  values
  ('5SC1', '呼吸和消化', 'Respiration and Digestion', 3, 1, true),
  ('5SC2', '生殖與發育', 'Reproduction and Development', 3, 2, true),
  ('5SC3', '空氣的特性', 'Properties of Air', 3, 3, true),
  ('5SC4', '可逆轉和不可逆轉的變化', 'Reversible and Irreversible Changes', 3, 4, true),
  ('5SC5', '顯微鏡下的微生物', 'Microorganisms under the Microscope', 3, 5, true),
  ('5SC6', '環境問題與可持續發展', 'Environmental Problems and Sustainable Development', 3, 6, true),
  ('5SC7', '科技創造未來', 'Technology Creates the Future', 3, 7, true)
)
insert into public.curriculum_nodes
  (domain_id, code, title_zh, title_en, difficulty, sort_order, is_active)
select sd.id, u.code, u.title_zh, u.title_en, u.difficulty, u.sort_order, u.is_active
from science_domain sd cross join units u
where not exists (
  select 1 from public.curriculum_nodes n where n.code = u.code
);

create temporary table tmp_science_questions (
  node_code text not null,
  category text not null,
  question_text text not null,
  options jsonb not null,
  correct_answer jsonb not null,
  explanation text not null,
  hint text not null,
  difficulty integer not null
) on commit drop;

