  ('5SC1', '概念選擇', '【概念選擇】
關於「保持消化系統健康」，下列哪一項正確？', '[{"id":"a","text":"均衡飲食、細嚼慢嚥並定時進食"},{"id":"b","text":"完全不吃含纖維食物"},{"id":"c","text":"只吃肉類"},{"id":"d","text":"經常暴飲暴食"}]'::jsonb, '"a"'::jsonb, '「均衡飲食、細嚼慢嚥並定時進食」正確。良好飲食習慣及足夠纖維有助消化和排便。', '先判斷每個選項是否符合課文中的科學概念。', 2),
  ('5SC1', '概念選擇', '【概念選擇】
關於「保護呼吸系統」，下列哪一項正確？', '[{"id":"a","text":"吸入二手煙沒有影響"},{"id":"b","text":"在密閉房間燃點大量香薰"},{"id":"c","text":"運動時用手掩住口鼻"},{"id":"d","text":"拒絕吸煙並保持空氣流通"}]'::jsonb, '"d"'::jsonb, '「拒絕吸煙並保持空氣流通」正確。煙霧和污濁空氣會刺激及損害呼吸系統。', '先判斷每個選項是否符合課文中的科學概念。', 2),
  ('5SC1', '概念選擇', '【概念選擇】
