哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"橫膈膜向上移，胸腔擴張"},{"id":"b","text":"肺部主動把胸腔撐大"},{"id":"c","text":"橫膈膜向上移，胸腔縮小"},{"id":"d","text":"橫膈膜向下移，胸腔縮小"}]'::jsonb, '"c"'::jsonb, '應選「橫膈膜向上移，胸腔縮小」，因為呼氣時胸腔容積減小，空氣流出。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 2),
  ('5SC1', '生活情境', '【生活情境】
