  ('5SC1', '多項陳述', '【多項陳述】
關於「保持消化系統健康」：
① 均衡飲食、細嚼慢嚥並定時進食
② 只吃肉類
③ 良好飲食習慣及足夠纖維有助消化和排便。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"①和③"},{"id":"c","text":"只有②"},{"id":"d","text":"①、②和③"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC1', '多項陳述', '【多項陳述】
