哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"未充氣氣球必定較重"},{"id":"b","text":"氣球顏色決定空氣重量"},{"id":"c","text":"空氣完全沒有質量"},{"id":"d","text":"充氣氣球的重量比同款未充氣氣球稍大"}]'::jsonb, '"d"'::jsonb, '應選「充氣氣球的重量比同款未充氣氣球稍大」，因為空氣是物質，因此具有重量。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 1),
  ('5SC3', '生活情境', '【生活情境】
【生活情境】子晴在生活中遇到與「空氣的成分」有關的問題，並提出四個解釋或做法。
哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"空氣主要由氮氣和氧氣組成"},{"id":"b","text":"空氣只有氧氣"},{"id":"c","text":"空氣主要是二氧化碳"},{"id":"d","text":"空氣沒有任何氣體"}]'::jsonb, '"a"'::jsonb, '應選「空氣主要由氮氣和氧氣組成」，因為空氣是多種氣體的混合物，氮氣最多，氧氣約佔五分之一。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 3),
  ('5SC3', '生活情境', '【生活情境】
【生活情境】美欣在生活中遇到與「風的形成」有關的問題，並提出四個解釋或做法。
哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"海水停止流動形成風"},{"id":"b","text":"聲音振動就是風"},{"id":"c","text":"空氣流動形成風"},{"id":"d","text":"只有樹葉搖動才會製造風"}]'::jsonb, '"c"'::jsonb, '應選「空氣流動形成風」，因為受熱不均會造成空氣流動，空氣的流動就是風。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 3),
  ('5SC3', '實驗探究', '【實驗探究】
【實驗探究】同學進行「把充氣瓶放入冰水和溫水」。他們希望進行公平測試。
這項探究中，哪組變因配對正確？', '[{"id":"a","text":"改變：氣球周長；量度：瓶子及觀察時間；控制：水溫"},{"id":"b","text":"改變所有條件；只量度水溫"},{"id":"c","text":"改變：水溫；量度：氣球周長；控制：瓶子及觀察時間"},{"id":"d","text":"不需控制變因；只記錄支持猜想的結果"}]'::jsonb, '"c"'::jsonb, '探究刻意改變「水溫」，量度「氣球周長」，並保持「瓶子及觀察時間」相同，才能公平比較。', '找出刻意改變、實際量度和保持相同的條件。', 3),
  ('5SC3', '實驗探究', '【實驗探究】
