  ('5SC3', '多項陳述', '【多項陳述】
關於「冷空氣的變化」：
① 空氣遇冷通常收縮
② 空氣遇冷一定燃燒
③ 溫度降低時空氣粒子運動減慢，體積通常減小。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"①、②和③"},{"id":"c","text":"只有②"},{"id":"d","text":"②和③"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 2),
  ('5SC3', '多項陳述', '【多項陳述】
關於「氣壓」：
① 空氣向各方向施加壓力
② 氣壓只向下
③ 空氣粒子運動會向物體各方向產生壓力。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"只有②"},{"id":"c","text":"②和③"},{"id":"d","text":"①、②和③"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC3', '多項陳述', '【多項陳述】
關於「氣壓的應用」：
① 用吸管喝水與氣壓差有關
② 吸管把水變成氣體
③ 吸走部分空氣後，外界氣壓把液體推上吸管。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"②和③"},{"id":"c","text":"①和③"},{"id":"d","text":"①、②和③"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC3', '多項陳述', '【多項陳述】
關於「海陸風原理」：
① 陸地與海洋受熱速度不同造成空氣流動
② 海水完全不吸熱
③ 海陸升溫和降溫速度不同，造成氣壓差和空氣流動。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"只有②"},{"id":"c","text":"①、②和③"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC3', '多項陳述', '【多項陳述】
關於「熱空氣的變化」：
① 空氣受熱會膨脹
② 空氣受熱會凝固
③ 空氣受熱時粒子運動加快，通常令體積增大。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"②和③"},{"id":"c","text":"①、②和③"},{"id":"d","text":"只有②"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 1),
  ('5SC3', '多項陳述', '【多項陳述】
關於「空氣佔有空間」：
① 倒扣杯內的空氣會阻止水立即進入
② 空氣沒有體積
③ 空氣雖看不見，仍會佔據空間。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"只有②"},{"id":"c","text":"①、②和③"},{"id":"d","text":"②和③"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC3', '多項陳述', '【多項陳述】
關於「空氣可被壓縮」：
① 封閉針筒內的空氣受壓後體積減小
② 空氣受壓後完全消失
③ 氣體粒子間距較大，所以空氣可以被壓縮。
以上哪些陳述正確？', '[{"id":"a","text":"①、②和③"},{"id":"b","text":"只有②"},{"id":"c","text":"①和③"},{"id":"d","text":"②和③"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 2),
  ('5SC3', '多項陳述', '【多項陳述】
關於「空氣有重量」：
① 充氣氣球的重量比同款未充氣氣球稍大
② 空氣完全沒有質量
③ 空氣是物質，因此具有重量。
以上哪些陳述正確？', '[{"id":"a","text":"①、②和③"},{"id":"b","text":"②和③"},{"id":"c","text":"①和③"},{"id":"d","text":"只有②"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 1),
  ('5SC3', '多項陳述', '【多項陳述】
關於「空氣的成分」：
① 空氣主要由氮氣和氧氣組成
② 空氣只有氧氣
③ 空氣是多種氣體的混合物，氮氣最多，氧氣約佔五分之一。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"①和③"},{"id":"c","text":"①、②和③"},{"id":"d","text":"只有②"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC3', '多項陳述', '【多項陳述】
關於「風的形成」：
① 空氣流動形成風
② 海水停止流動形成風
③ 受熱不均會造成空氣流動，空氣的流動就是風。
以上哪些陳述正確？', '[{"id":"a","text":"①、②和③"},{"id":"b","text":"①和③"},{"id":"c","text":"只有②"},{"id":"d","text":"②和③"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
