下列哪項判斷和修正最恰當？', '[{"id":"a","text":"說法完全正確，不用修改"},{"id":"b","text":"說法不正確，應改為：木材燃燒後不能簡單回復成木材"},{"id":"c","text":"應刪去整個概念，因為燃燒不能研究"},{"id":"d","text":"只需把說法改成：燃燒只是形狀改變"}]'::jsonb, '"b"'::jsonb, '原說法不正確，正確概念是「木材燃燒後不能簡單回復成木材」。燃燒會形成灰燼和氣體等新物質，屬不可逆轉變化。', '先判斷人物的說法，再找出符合科學證據的修正。', 3),
  ('5SC4', '判斷修正', '【判斷修正】
詠恩說：「只有陽光能使鐵生鏽。」
下列哪項判斷和修正最恰當？', '[{"id":"a","text":"只需把說法改成：完全乾燥密封最易生鏽"},{"id":"b","text":"說法完全正確，不用修改"},{"id":"c","text":"說法不正確，應改為：鐵、水和空氣共同存在會促進生鏽"},{"id":"d","text":"應刪去整個概念，因為鐵生鏽不能研究"}]'::jsonb, '"c"'::jsonb, '原說法不正確，正確概念是「鐵、水和空氣共同存在會促進生鏽」。鐵與水和氧氣反應形成鐵鏽，屬不可逆轉變化。', '先判斷人物的說法，再找出符合科學證據的修正。', 4),
  ('5SC4', '判斷修正', '【判斷修正】
文軒說：「刮去保護層。」
下列哪項判斷和修正最恰當？', '[{"id":"a","text":"說法完全正確，不用修改"},{"id":"b","text":"只需把說法改成：長期浸在鹽水"},{"id":"c","text":"說法不正確，應改為：塗油或油漆可隔絕水和空氣"},{"id":"d","text":"應刪去整個概念，因為防止鐵生鏽不能研究"}]'::jsonb, '"c"'::jsonb, '原說法不正確，正確概念是「塗油或油漆可隔絕水和空氣」。保護層減少鐵同時接觸水和氧氣。', '先判斷人物的說法，再找出符合科學證據的修正。', 1),
  ('5SC4', '生活情境', '【生活情境】
【生活情境】可嵐在生活中遇到與「不可逆轉的變化」有關的問題，並提出四個解釋或做法。
哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"完全沒有新物質形成"},{"id":"b","text":"一定只改變大小"},{"id":"c","text":"任何冷卻都能回復"},{"id":"d","text":"變化後難以用簡單方法回復原物質"}]'::jsonb, '"d"'::jsonb, '應選「變化後難以用簡單方法回復原物質」，因為不可逆轉變化常會形成性質不同的新物質。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 3),
  ('5SC4', '生活情境', '【生活情境】
