哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"只記錄支持猜想的結果"},{"id":"b","text":"每組使用不同大小樣本"},{"id":"c","text":"一次只改變一個主要變因"},{"id":"d","text":"同時改變所有條件"}]'::jsonb, '"c"'::jsonb, '應選「一次只改變一個主要變因」，因為控制其他條件才能較可靠地判斷主要變因的影響。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 4),
  ('5SC4', '生活情境', '【生活情境】
