哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"物質一定產生新物質"},{"id":"b","text":"變化後永遠不能回復"},{"id":"c","text":"只包括燃燒"},{"id":"d","text":"物質能以簡單方法回復原來狀態"}]'::jsonb, '"d"'::jsonb, '應選「物質能以簡單方法回復原來狀態」，因為可逆轉變化通常沒有形成新物質，並能較容易回復。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 3),
  ('5SC4', '生活情境', '【生活情境】
