哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"把泥膠壓扁通常可重新塑形"},{"id":"b","text":"壓扁泥膠必定形成新物質"},{"id":"c","text":"所有形狀改變都不可逆轉"},{"id":"d","text":"泥膠改形後質量必定增加"}]'::jsonb, '"a"'::jsonb, '應選「把泥膠壓扁通常可重新塑形」，因為只改變形狀而物質本質不變，通常可以逆轉。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 2),
  ('5SC4', '生活情境', '【生活情境】
