哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"融化、凝固、蒸發和凝結通常可逆轉"},{"id":"b","text":"水結冰屬燃燒"},{"id":"c","text":"水蒸發後永遠消失"},{"id":"d","text":"冰融化會產生新物質"}]'::jsonb, '"a"'::jsonb, '應選「融化、凝固、蒸發和凝結通常可逆轉」，因為水在固、液、氣態之間轉變，物質仍是水。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 4),
