這項探究中，哪組變因配對正確？', '[{"id":"a","text":"不需控制變因；只記錄支持猜想的結果"},{"id":"b","text":"改變：是否加熱；量度：顏色、氣味及硬度變化；控制：物料分量及加熱時間"},{"id":"c","text":"改變所有條件；只量度是否加熱"},{"id":"d","text":"改變：顏色、氣味及硬度變化；量度：物料分量及加熱時間；控制：是否加熱"}]'::jsonb, '"b"'::jsonb, '探究刻意改變「是否加熱」，量度「顏色、氣味及硬度變化」，並保持「物料分量及加熱時間」相同，才能公平比較。', '找出刻意改變、實際量度和保持相同的條件。', 4),
