哪項做法最能令觀察記錄客觀可靠？', '[{"id":"a","text":"使用合適工具量度鐵鏽面積，記下單位並重複觀察"},{"id":"b","text":"只寫『有變化』而不記錄數值"},{"id":"c","text":"只畫最符合猜想的一次結果"},{"id":"d","text":"用感覺估計並在實驗後補寫數據"}]'::jsonb, '"a"'::jsonb, '使用工具量度「鐵鏽面積」、標示單位並重複觀察，所得資料較客觀，也方便比較。', '可靠記錄要包括實際量度、單位和重複結果。', 1),
  ('5SC4', '多項陳述', '【多項陳述】
關於「不可逆轉的變化」：
① 變化後難以用簡單方法回復原物質
② 一定只改變大小
③ 不可逆轉變化常會形成性質不同的新物質。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"②和③"},{"id":"c","text":"①、②和③"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC4', '多項陳述', '【多項陳述】
關於「公平測試」：
① 一次只改變一個主要變因
② 同時改變所有條件
③ 控制其他條件才能較可靠地判斷主要變因的影響。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"只有②"},{"id":"c","text":"①、②和③"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC4', '多項陳述', '【多項陳述】
關於「可逆轉的變化」：
① 物質能以簡單方法回復原來狀態
② 物質一定產生新物質
③ 可逆轉變化通常沒有形成新物質，並能較容易回復。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"①和③"},{"id":"c","text":"②和③"},{"id":"d","text":"①、②和③"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC4', '多項陳述', '【多項陳述】
關於「形狀改變」：
① 把泥膠壓扁通常可重新塑形
② 壓扁泥膠必定形成新物質
③ 只改變形狀而物質本質不變，通常可以逆轉。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"②和③"},{"id":"c","text":"①、②和③"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 2),
  ('5SC4', '多項陳述', '【多項陳述】
關於「水的三態變化」：
① 融化、凝固、蒸發和凝結通常可逆轉
② 水結冰屬燃燒
③ 水在固、液、氣態之間轉變，物質仍是水。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"①、②和③"},{"id":"c","text":"②和③"},{"id":"d","text":"只有②"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC4', '多項陳述', '【多項陳述】
關於「溶解與回收」：
① 鹽溶於水後可用蒸發方法取回
② 鹽溶解後變成另一種物質
③ 溶解沒有把鹽變成新物質，可蒸發水分回收鹽。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"①、②和③"},{"id":"c","text":"①和③"},{"id":"d","text":"②和③"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 1),
  ('5SC4', '多項陳述', '【多項陳述】
關於「烹煮食物」：
① 雞蛋煮熟通常屬不可逆轉變化
② 熟蛋冷卻便變回生蛋
③ 加熱使蛋白質發生難以回復的變化。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"①和③"},{"id":"c","text":"①、②和③"},{"id":"d","text":"②和③"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC4', '多項陳述', '【多項陳述】
關於「燃燒」：
① 木材燃燒後不能簡單回復成木材
② 灰燼加水便會變回木材
③ 燃燒會形成灰燼和氣體等新物質，屬不可逆轉變化。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"①和③"},{"id":"c","text":"①、②和③"},{"id":"d","text":"只有②"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC4', '多項陳述', '【多項陳述】
關於「鐵生鏽」：
① 鐵、水和空氣共同存在會促進生鏽
② 只有陽光能使鐵生鏽
③ 鐵與水和氧氣反應形成鐵鏽，屬不可逆轉變化。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"只有②"},{"id":"c","text":"①和③"},{"id":"d","text":"①、②和③"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 1),
  ('5SC4', '多項陳述', '【多項陳述】
