以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"②和③"},{"id":"c","text":"①和③"},{"id":"d","text":"①、②和③"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 2),
