哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"部分微生物分解食物會令食物變壞"},{"id":"b","text":"腐壞與微生物完全無關"},{"id":"c","text":"食物變壞只因顏色改變"},{"id":"d","text":"所有腐壞食物加熱後都安全"}]'::jsonb, '"a"'::jsonb, '應選「部分微生物分解食物會令食物變壞」，因為微生物繁殖可改變食物的氣味、外觀和安全性。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 2),
  ('5SC5', '實驗探究', '【實驗探究】
