哪個實驗次序最合理？', '[{"id":"a","text":"只看別人結果 → 猜測答案 → 不記錄數據 → 宣布證明成功"},{"id":"b","text":"進行實驗 → 刪去異常數據 → 才決定量度甚麼 → 不作結論"},{"id":"c","text":"先寫結論 → 只做一次 → 改變所有條件 → 選擇喜歡的數據"},{"id":"d","text":"提出可測試問題 → 設定變因 → 進行並重複量度 → 記錄結果 → 根據證據下結論"}]'::jsonb, '"d"'::jsonb, '合理次序由可測試問題開始，先設定變因，再量度及記錄，最後才根據證據作結論。', '科學探究應先有問題和變因，之後量度、記錄和以證據下結論。', 1),
