哪項做法最能令觀察記錄客觀可靠？', '[{"id":"a","text":"只畫最符合猜想的一次結果"},{"id":"b","text":"使用合適工具量度出現腐壞特徵的時間，記下單位並重複觀察"},{"id":"c","text":"只寫『有變化』而不記錄數值"},{"id":"d","text":"用感覺估計並在實驗後補寫數據"}]'::jsonb, '"b"'::jsonb, '使用工具量度「出現腐壞特徵的時間」、標示單位並重複觀察，所得資料較客觀，也方便比較。', '可靠記錄要包括實際量度、單位和重複結果。', 1),
  ('5SC5', '多項陳述', '【多項陳述】
關於「保存食物」：
① 冷藏、乾燥或密封可減慢部分微生物生長
② 把食物放在陽光下必定永久保存
③ 降低溫度或水分、減少污染可延緩腐壞。
以上哪些陳述正確？', '[{"id":"a","text":"①、②和③"},{"id":"b","text":"只有②"},{"id":"c","text":"②和③"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC5', '多項陳述', '【多項陳述】
關於「安全研究微生物」：
① 使用密封樣本並由老師指導處理
② 直接嗅聞未知培養物
③ 未知微生物可能有害，必須採取安全和衞生措施。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"只有②"},{"id":"c","text":"①、②和③"},{"id":"d","text":"②和③"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC5', '多項陳述', '【多項陳述】
關於「微生物」：
① 微生物通常要借助顯微鏡才看得清楚
② 所有微生物都比昆蟲大
③ 微生物體積微小，種類和作用很多。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"①、②和③"},{"id":"c","text":"只有②"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC5', '多項陳述', '【多項陳述】
關於「微生物的生長條件」：
① 溫暖、潮濕和有養分通常有利生長
② 極度乾燥必定最快生長
③ 不同微生物需要的條件有差異，但溫暖潮濕常有利繁殖。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"①、②和③"},{"id":"c","text":"①和③"},{"id":"d","text":"②和③"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 1),
  ('5SC5', '多項陳述', '【多項陳述】
關於「微生物的種類」：
① 細菌、真菌、病毒和部分藻類屬微生物
② 石頭和水滴都是微生物
③ 微生物包括多個類群，不是單一種類。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"①、②和③"},{"id":"c","text":"②和③"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC5', '多項陳述', '【多項陳述】
關於「有益微生物」：
① 酵母可用來製作麵包
② 所有細菌都令人患病
③ 人類會利用某些微生物發酵和製作食品。
以上哪些陳述正確？', '[{"id":"a","text":"②和③"},{"id":"b","text":"①、②和③"},{"id":"c","text":"只有②"},{"id":"d","text":"①和③"}]'::jsonb, '"d"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC5', '多項陳述', '【多項陳述】
關於「藥物與微生物」：
① 抗生素只應按醫生指示用於合適的細菌感染
② 抗生素能治療所有病毒感染
③ 不當使用抗生素會降低治療效果並增加耐藥性風險。
以上哪些陳述正確？', '[{"id":"a","text":"①、②和③"},{"id":"b","text":"①和③"},{"id":"c","text":"只有②"},{"id":"d","text":"②和③"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 1),
  ('5SC5', '多項陳述', '【多項陳述】
關於「防止傳播」：
① 勤洗手、妥善處理食物及咳嗽時掩口鼻
② 共用個人餐具
③ 良好衞生可減少有害微生物傳播。
以上哪些陳述正確？', '[{"id":"a","text":"①、②和③"},{"id":"b","text":"①和③"},{"id":"c","text":"只有②"},{"id":"d","text":"②和③"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 2),
  ('5SC5', '多項陳述', '【多項陳述】
關於「顯微鏡觀察」：
① 先用低倍鏡尋找影像再調焦
② 先用最高倍鏡並快速轉動鏡筒
③ 由低倍開始較易找到影像，正確調焦可保護儀器和樣本。
以上哪些陳述正確？', '[{"id":"a","text":"只有②"},{"id":"b","text":"①和③"},{"id":"c","text":"②和③"},{"id":"d","text":"①、②和③"}]'::jsonb, '"b"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 3),
  ('5SC5', '多項陳述', '【多項陳述】
關於「食物腐壞」：
① 部分微生物分解食物會令食物變壞
② 腐壞與微生物完全無關
③ 微生物繁殖可改變食物的氣味、外觀和安全性。
以上哪些陳述正確？', '[{"id":"a","text":"①、②和③"},{"id":"b","text":"只有②"},{"id":"c","text":"①和③"},{"id":"d","text":"②和③"}]'::jsonb, '"c"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 2),
  ('5SC5', '數據分析', '【數據分析】
【雙重條件】選擇測試「保存食物」的方案。條件：測量至少3次；每次均控制「水果種類、大小及日數」。
甲：2次／有控制 乙：3次／沒有控制 丙：4次／有控制 丁：1次／沒有控制
哪個方案同時符合兩項條件？', '[{"id":"a","text":"乙"},{"id":"b","text":"丙"},{"id":"c","text":"丁"},{"id":"d","text":"甲"}]'::jsonb, '"b"'::jsonb, '丙方案測量4次，而且有控制指定條件，因此同時符合兩項要求。', '逐一檢查測量次數和控制變因兩項條件。', 4),
  ('5SC5', '數據分析', '【數據分析】
