哪個解釋或做法最符合科學原理？', '[{"id":"a","text":"滿足現在需要而不損害後代滿足需要的能力"},{"id":"b","text":"完全停止所有人類活動"},{"id":"c","text":"只追求短期經濟利益"},{"id":"d","text":"把資源用完再尋找替代品"}]'::jsonb, '"a"'::jsonb, '應選「滿足現在需要而不損害後代滿足需要的能力」，因為可持續發展要兼顧環境、社會和經濟需要。', '把課堂所學應用到情境，留意選項有沒有使用錯誤概念。', 4),
  ('5SC6', '生活情境', '【生活情境】
