這項探究中，哪組變因配對正確？', '[{"id":"a","text":"改變：每日用電量；量度：課室設備及使用時間；控制：是否採用節能措施"},{"id":"b","text":"不需控制變因；只記錄支持猜想的結果"},{"id":"c","text":"改變：是否採用節能措施；量度：每日用電量；控制：課室設備及使用時間"},{"id":"d","text":"改變所有條件；只量度是否採用節能措施"}]'::jsonb, '"c"'::jsonb, '探究刻意改變「是否採用節能措施」，量度「每日用電量」，並保持「課室設備及使用時間」相同，才能公平比較。', '找出刻意改變、實際量度和保持相同的條件。', 2),
