哪項做法最能令觀察記錄客觀可靠？', '[{"id":"a","text":"用感覺估計並在實驗後補寫數據"},{"id":"b","text":"只寫『有變化』而不記錄數值"},{"id":"c","text":"使用合適工具量度每日用電量，記下單位並重複觀察"},{"id":"d","text":"只畫最符合猜想的一次結果"}]'::jsonb, '"c"'::jsonb, '使用工具量度「每日用電量」、標示單位並重複觀察，所得資料較客觀，也方便比較。', '可靠記錄要包括實際量度、單位和重複結果。', 4),
