哪項做法最能令觀察記錄客觀可靠？', '[{"id":"a","text":"使用合適工具量度每人每公里排放量，記下單位並重複觀察"},{"id":"b","text":"用感覺估計並在實驗後補寫數據"},{"id":"c","text":"只畫最符合猜想的一次結果"},{"id":"d","text":"只寫『有變化』而不記錄數值"}]'::jsonb, '"a"'::jsonb, '使用工具量度「每人每公里排放量」、標示單位並重複觀察，所得資料較客觀，也方便比較。', '可靠記錄要包括實際量度、單位和重複結果。', 1),
  ('5SC6', '多項陳述', '【多項陳述】
關於「可持續發展」：
① 滿足現在需要而不損害後代滿足需要的能力
② 只追求短期經濟利益
③ 可持續發展要兼顧環境、社會和經濟需要。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"②和③"},{"id":"c","text":"只有②"},{"id":"d","text":"①、②和③"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 4),
  ('5SC6', '多項陳述', '【多項陳述】
關於「噪音污染」：
