③ 源頭減廢通常比事後處理更能節省資源。
以上哪些陳述正確？', '[{"id":"a","text":"①和③"},{"id":"b","text":"②和③"},{"id":"c","text":"①、②和③"},{"id":"d","text":"只有②"}]'::jsonb, '"a"'::jsonb, '①是正確概念，③提供合理解釋；②與科學概念不符，所以答案是①和③。', '逐項判斷：①是科學概念；再檢查②和③是否與它一致。', 2),
  ('5SC6', '多項陳述', '【多項陳述】
